# Independent recheck (skeptic v-ex-dimension-logic): generic Jacobian rank of the block-2 program map in V(x)V and
# V(x)L2V, written from scratch: B generated by BFS as a matrix group from hand-typed generators, A = span rho(B),
# full Jacobian by exact forward-mode over every coordinate direction (no sketch), rank by SVD.
import sys, itertools, numpy as np
np.set_printoptions(linewidth=200)
m = 2; n = 4
def perm(p):
    M = np.zeros((n, n), complex)
    for x in range(n): M[p(x), x] = 1          # column convention differs from dimcount on purpose
    return M
X0 = perm(lambda x: x ^ 1); X1 = perm(lambda x: x ^ 2)
CN01 = perm(lambda x: x ^ ((x & 1) << 1)); CN10 = perm(lambda x: x ^ ((x >> 1) & 1))
S0 = np.diag([1j if (x & 1) else 1 for x in range(n)]); S1 = np.diag([1j if (x & 2) else 1 for x in range(n)])
gens = [X0, X1, CN01, CN10, S0, S1, 1j * np.eye(n)]
def key(M): return tuple(np.round(M.flatten() * 2).astype(complex).tolist())
seen = {key(np.eye(n)): np.eye(n, dtype=complex)}; frontier = [np.eye(n, dtype=complex)]
while frontier:
    nf = []
    for g in frontier:
        for h in gens:
            M = h @ g; k = key(M)
            if k not in seen: seen[k] = M; nf.append(M)
    frontier = nf
Bgrp = list(seen.values()); print('|B| =', len(Bgrp))
ca, cb = (1 + 1j) / 2, (1 - 1j) / 2
D0 = ca * np.eye(n) + cb * X0; D1 = ca * np.eye(n) + cb * X1
K = D1 @ D0
rep = sys.argv[1]
def ext2(g):
    subs = list(itertools.combinations(range(n), 2)); M = np.zeros((6, 6), complex)
    for a, S in enumerate(subs):
        for b, T in enumerate(subs): M[a, b] = np.linalg.det(g[np.ix_(S, T)])
    return M
rho = (lambda g: np.kron(g, g)) if rep == 'VV' else (lambda g: np.kron(g, ext2(g)))
d = rho(np.eye(n)).shape[0]
Mat = np.array([rho(b).flatten() for b in Bgrp])
u, s, vh = np.linalg.svd(Mat, full_matrices=False)
dimA = int((s > 1e-8 * s[0]).sum()); Abasis = vh[:dimA].conj().reshape(dimA, d, d)  # rows of vh span row space
# check: Abasis spans rho(B)
print('dim A =', dimA)
R = rho(D0); Kr = rho(K)
# C[G] span: closure of A under left mult by R
CG = Abasis.reshape(dimA, -1)
for it in range(6):
    new = np.concatenate([CG, np.einsum('ij,ajk->aik', R, CG.reshape(-1, d, d)).reshape(-1, d * d),
                          np.einsum('aij,bjk->abik', Abasis, CG.reshape(-1, d, d)[:40]).reshape(-1, d * d)], 0)
    u2, s2, v2 = np.linalg.svd(new, full_matrices=False); r2 = int((s2 > 1e-8 * s2[0]).sum())
    CG = v2[:r2]
print('dim rho(C[G]) =', CG.shape[0])
dimCG = CG.shape[0]
rng = np.random.default_rng(int(sys.argv[3]) if len(sys.argv) > 3 else 7)
def run(W, s):
    # sources: inputs e_l (d x dW with identity in block l), outputs u_1..u_s ; params per source a in A
    slots = [W + j for j in range(s)] + [W + s] * W
    P = sum(slots) * dimA
    coef = [rng.normal(size=(k, dimA)) + 1j * rng.normal(size=(k, dimA)) for k in slots]
    mats = [np.tensordot(c, Abasis, axes=(1, 0)) for c in coef]
    E = []
    for l in range(W):
        Xl = np.zeros((d, d * W), complex); Xl[:, l * d:(l + 1) * d] = np.eye(d); E.append(Xl)
    srcs = list(E)
    for j in range(s):
        c = sum(mats[j][i] @ srcs[i] for i in range(len(srcs)))
        srcs.append(R @ c / np.linalg.norm(c))   # rescaling an output is a reparametrisation (same image dim)
    # Jacobian columns: derivative w.r.t. coefficient (slot k, source i, basis a)
    cols = []
    for kslot in range(len(slots)):
        for i in range(slots[kslot]):
            # tangent: d(coef[kslot][i]) = Abasis[a] for all a at once (batch over a)
            dsrc = [np.zeros((dimA, d, d * W), complex) for _ in range(W)]
            for j in range(s):
                dc = np.zeros((dimA, d, d * W), complex)
                for ii in range(len(dsrc)):
                    dc += np.matmul(mats[j][ii], dsrc[ii])
                if j == kslot: dc += np.matmul(Abasis, srcs[i])
                # derivative of normalised output: project (keeps rank of image since normalisation is a gauge);
                # simpler: do not differentiate the norm (treat 1/||c|| as a fixed constant) -> exact for the
                # unnormalised program with rescaled later coefficients
                c0 = sum(mats[j][q] @ srcs[q] for q in range(W + j))
                dsrc.append(np.matmul(R, dc) / np.linalg.norm(c0))
            outs = []
            for t in range(W):
                kk = s + t
                do = np.zeros((dimA, d, d * W), complex)
                for ii in range(len(dsrc)):
                    do += np.matmul(mats[kk][ii], dsrc[ii])
                if kk == kslot: do += np.matmul(Abasis, srcs[i])
                outs.append(do.reshape(dimA, -1))
            cols.append(np.concatenate(outs, 1))
    J = np.concatenate(cols, 0)
    sv = np.linalg.svd(J, compute_uv=False)
    r = int((sv > 1e-9 * sv[0]).sum())
    print(f'W={W} s={s}: P={P} Eeff={W*W*dimCG} rank={r}  sv[r-1]/sv0={sv[r-1]/sv[0]:.2e} sv[r]/sv0={(sv[r]/sv[0]) if r < len(sv) else 0:.2e}', flush=True)
for W, s in [tuple(map(int, x.split(','))) for x in sys.argv[2].split(';')]:
    run(W, s)
